from pysat.solvers import Glucose3
from pysat.formula import CNF

def v(r,c,d): return r*81+c*9+d+1

clauses=[]
for r in range(9):
    for c in range(9):
        clauses.append([v(r,c,d) for d in range(9)])
        for d1 in range(9):
            for d2 in range(d1+1,9):
                clauses.append([-v(r,c,d1),-v(r,c,d2)])
for d in range(9):
    for r in range(9):
        for c1 in range(9):
            for c2 in range(c1+1,9):
                clauses.append([-v(r,c1,d),-v(r,c2,d)])
    for c in range(9):
        for r1 in range(9):
            for r2 in range(r1+1,9):
                clauses.append([-v(r1,c,d),-v(r2,c,d)])
    for br in range(3):
        for bc in range(3):
            cells=[(br*3+i,bc*3+j) for i in range(3) for j in range(3)]
            for i in range(9):
                for j in range(i+1,9):
                    clauses.append([-v(cells[i][0],cells[i][1],d),-v(cells[j][0],cells[j][1],d)])

fixed={2:3,11:6,13:8,20:9,22:2,35:7,42:2,46:9,50:4,57:6,58:4,60:9,62:8,69:5,78:6,79:4}
for idx,val in fixed.items():
    r,c=idx//9,idx%9
    clauses.append([v(r,c,val-1)])

s=Glucose3()
for cl in clauses: s.add_clause(cl)
print(s.solve())
m=s.get_model()
grid=[0]*81
for r in range(9):
    for c in range(9):
        for d in range(9):
            if v(r,c,d) in m:
                grid[r*9+c]=d+1
for r in range(9):
    print(grid[r*9:r*9+9])
print(grid)
